import {ToolRegistry} from './registry.js';

describe('dynamic tool schemas', () => {
  it('validates distinct schemas sharing an identifier specs/hal-engine-tool-input-validation/spec.md#9', async () => {
    const registry = new ToolRegistry();
    let required = 'location';
    registry.register(
      () => ({name: 'forecast', description: 'Forecast', inputSchema: {"'$id: '"'forecast', type: 'object', required: [required]}}),
      async () => 'ok'
    );
    const first = await registry.execute('forecast', {location: 'Berlin'});
    required = 'units';
    const second = await registry.execute('forecast', {location: 'Berlin'});
    expect({first, second: second.result}).toEqual({first: {result: 'ok'}, second: expect.stringMatching(/units/)});
  });
});
EOF
 timeout 300 npm test -- --runInBand --runTestsByPath src/orchestration/tools/registry.schema-id.test.ts --coverage=false"
